function ScratchPad({ W: W3 = 760, H = 380, background = null, overlay = null, resetKey, title = "Scratch pad — sketch your answer", extra = null }) {
  const [strokes, setStrokes] = useState([]);
  const [pen, setPen] = useState(PENS[0].c);
  const [erase, setErase] = useState(false);
  const [width, setWidth] = useState(3);
  const live = useRef(null);
  const svgRef = useRef(null);
  const [, force] = useState(0);
  useEffect(() => {
    setStrokes([]);
    live.current = null;
  }, [resetKey]);
  const at = (e) => {
    const r = svgRef.current.getBoundingClientRect();
    return [(e.clientX - r.left) / r.width * W3, (e.clientY - r.top) / r.height * H];
  };
  const rubOut = (p) => setStrokes((ss) => ss.filter((s) => !s.pts.some((q) => Math.hypot(q[0] - p[0], q[1] - p[1]) < 12)));
  const down = (e) => {
    e.preventDefault();
    try {
      svgRef.current.setPointerCapture(e.pointerId);
    } catch (_) {
    }
    const p = at(e);
    if (erase) {
      live.current = { erasing: true };
      rubOut(p);
      return;
    }
    live.current = { c: pen, w: width * (e.pointerType === "pen" && e.pressure ? 0.6 + e.pressure : 1), pts: [p] };
    force((n) => n + 1);
  };
  const move = (e) => {
    const s = live.current;
    if (!s) return;
    const p = at(e);
    if (s.erasing) {
      rubOut(p);
      return;
    }
    const last = s.pts[s.pts.length - 1];
    if (Math.hypot(p[0] - last[0], p[1] - last[1]) < 1.5) return;
    s.pts.push(p);
    force((n) => n + 1);
  };
  const up = () => {
    const s = live.current;
    live.current = null;
    if (s && !s.erasing && s.pts.length) setStrokes((ss) => [...ss, s]);
  };
  return <div className="sp"><style>{CSS}</style><div className="sp-bar"><span className="sp-t">{title}</span>{PENS.map((p) => <button key={p.c} className={"sp-pen" + (!erase && pen === p.c ? " on" : "")} style={{ background: p.c }} title={`${p.name} pen`} aria-label={`${p.name} pen`} onClick={() => {
    setPen(p.c);
    setErase(false);
  }} />)}<button className={"sp-b" + (width > 3 ? " on" : "")} onClick={() => setWidth((w) => w > 3 ? 3 : 6)} title="thick / thin pen">{width > 3 ? "thick" : "thin"}</button><button className={"sp-b" + (erase ? " on" : "")} onClick={() => setErase((v) => !v)} title="rub out strokes">eraser</button><button className="sp-b" disabled={!strokes.length} onClick={() => setStrokes((ss) => ss.slice(0, -1))}>undo</button><button className="sp-b" disabled={!strokes.length} onClick={() => setStrokes([])}>clear</button><span className="sp-sp" />{extra}</div><svg
    ref={svgRef}
    className={"sp-svg" + (erase ? " erase" : "")}
    viewBox={`0 0 ${W3} ${H}`}
    onPointerDown={down}
    onPointerMove={move}
    onPointerUp={up}
    onPointerCancel={up}
    onPointerLeave={up}
  ><g style={{ pointerEvents: "none" }}>{background}</g>{strokes.map((s, i) => <path key={i} d={pathOf(s.pts)} fill="none" stroke={s.c} strokeWidth={s.w} strokeLinecap="round" strokeLinejoin="round" />)}{live.current && !live.current.erasing && <path d={pathOf(live.current.pts)} fill="none" stroke={live.current.c} strokeWidth={live.current.w} strokeLinecap="round" strokeLinejoin="round" />}<g style={{ pointerEvents: "none" }}>{overlay}</g></svg></div>;
}

