  const h = ccw ? `M ${cx - 1} ${cy - r - 4.5} L ${cx - 1} ${cy - r + 4.5} L ${cx - 8} ${cy - r} Z` : `M ${cx + 1} ${cy - r - 4.5} L ${cx + 1} ${cy - r + 4.5} L ${cx + 8} ${cy - r} Z`;
