      if (mb.rel2) out.push(<circle key={"r2" + mb.id} cx={SX(mb.b.x - mb.c * off)} cy={SY(mb.b.y - mb.s * off)} r={4.5 * k + 0.5} fill="#fff" stroke={C.hinge} strokeWidth={2 * k} />);
