      out.push(<text key={"n" + n.id} x={SX(n.x) + (compact ? -7 : -10)} y={SY(n.y) + (isBeam ? sup ? compact ? -8 : -10 : compact ? 13 : 18 : -8)} fontSize={compact ? 9 : 11.5} fontFamily={MONO2} fontWeight="700" fill={C.soft} stroke="#fff" strokeWidth="3" paintOrder="stroke" textAnchor="middle">{n.id}</text>);
